// Calculateur Intelligent et Résilient du Coût de Production IA

// Grille tarifaire (USD par 1M tokens)
const pricing = {
  "gpt-5": { input: 1.25, output: 5.0 },
  "gpt-5.6-terra": { input: 1.25, output: 5.0 },
  "gpt-5-mini": { input: 0.125, output: 1.0 },
  "gpt-5.4-mini": { input: 0.125, output: 1.0 },
  "gpt-4o": { input: 2.50, output: 10.0 },
  "gpt-4o-mini": { input: 0.15, output: 0.60 },
  "gemini-3.6-flash": { input: 0.30, output: 2.50 },
  "gemini-3-pro": { input: 2.00, output: 12.00 },
  "gemini-2.5-flash": { input: 0.30, output: 2.50 },
  "gemini-2.5-pro": { input: 1.25, output: 10.00 }
};

// Coûts unitaires par génération
const unitPricing = {
  "models/gemini-2.5-flash-image": 0.030,
  "models/gemini-3.1-flash-image": 0.030,
  "gpt-image-1-mini": 0.040,
  "gpt-image-1": 0.040,
  "default_image": 0.030,
  "models/veo-3.1-lite-generate-preview": 0.150,
  "sora-2": 0.200,
  "default_video": 0.150
};

function findPrice(modelName) {
  if (!modelName) return pricing["gpt-5-mini"];
  const cleanName = modelName.toLowerCase();
  if (pricing[cleanName]) return pricing[cleanName];
  const keys = Object.keys(pricing).sort((a, b) => b.length - a.length);
  for (const key of keys) {
    if (cleanName.includes(key)) {
      return pricing[key];
    }
  }
  return pricing["gpt-5-mini"];
}

// 1. Récupération Story ID
let storyId = null;
if ($('Creation_histoire_dans_supabase1').isExecuted) {
  storyId = $('Creation_histoire_dans_supabase1').first().json?.id;
} else if ($('Création histoire dans supabase').isExecuted) {
  storyId = $('Création histoire dans supabase').first().json?.id;
}

// 2. Coût des titres transmis via Webhook
let titleCostUsd = 0;
let titleInputTokens = 0;
let titleOutputTokens = 0;
if ($('Webhook').isExecuted) {
  const webhookBody = $('Webhook').first().json?.body || {};
  const titleCostObj = webhookBody.titleGenerationCost || {};
  titleCostUsd = Number(titleCostObj.total_cost_usd || 0);
  titleInputTokens = Number(titleCostObj.total_input_tokens || 0);
  titleOutputTokens = Number(titleCostObj.total_output_tokens || 0);
}

// 3. Modèles Textuels LLM
const textNodesToInspect = [
  { name: "Création histoire", fallbackModel: "gpt-5.6-terra", isAgent: true },
  { name: "Vérif création histoire", fallbackModel: "gpt-5-mini" },
  { name: "Contexte autour histoire", fallbackModel: "gpt-5-mini" },
  { name: "Allonge l'histoire", fallbackModel: "gpt-5" },
  { name: "Vérif création histoire1", fallbackModel: "gpt-5-mini" },
  { name: "Contexte autour histoire1", fallbackModel: "gpt-5-mini" },
  { name: "Analyze_image", fallbackModel: "gemini-3.6-flash" },
  { name: "Analyze image", fallbackModel: "gpt-5.4-mini" }
];

let totalInputTokens = titleInputTokens;
let totalOutputTokens = titleOutputTokens;
let totalCostFromLLM = 0;
const breakdown = [];

if (titleCostUsd > 0 || titleInputTokens > 0) {
  breakdown.push({
    node: "Generation_titres (Webhook)",
    type: "llm_text",
    model: "gpt-5-mini",
    input_tokens: titleInputTokens,
    output_tokens: titleOutputTokens,
    cost_usd: Number(titleCostUsd.toFixed(6))
  });
}

for (const item of textNodesToInspect) {
  const nodeName = item.name;
  if (!$(nodeName).isExecuted) continue;

  let nodeJson = {};
  try {
    nodeJson = $(nodeName).first().json || {};
  } catch (e) {
    continue;
  }

  let modelName = nodeJson.model || nodeJson.modelName || item.fallbackModel;
  let inTokens = 0;
  let outTokens = 0;

  if (item.isAgent) {
    const outText = nodeJson.output || "";
    outTokens = Math.ceil(outText.length / 3.8);
    inTokens = 1800;
  } else {
    if (nodeJson.usage) {
      inTokens = Number(nodeJson.usage.prompt_tokens || nodeJson.usage.input_tokens || 0);
      outTokens = Number(nodeJson.usage.completion_tokens || nodeJson.usage.output_tokens || 0);
    } else if (nodeJson.usageMetadata) {
      inTokens = Number(nodeJson.usageMetadata.promptTokenCount || 0);
      outTokens = Number(nodeJson.usageMetadata.candidatesTokenCount || 0);
    } else {
      const text = typeof nodeJson === 'string' ? nodeJson : JSON.stringify(nodeJson);
      outTokens = Math.ceil(text.length / 4);
      inTokens = 1200;
    }
  }

  const modelRate = findPrice(modelName);
  const costIn = (inTokens / 1000000) * modelRate.input;
  const costOut = (outTokens / 1000000) * modelRate.output;
  const costTotal = Number((costIn + costOut).toFixed(6));

  totalInputTokens += inTokens;
  totalOutputTokens += outTokens;
  totalCostFromLLM += costTotal;

  breakdown.push({
    node: nodeName,
    type: "llm_text",
    model: modelName,
    input_tokens: inTokens,
    output_tokens: outTokens,
    cost_usd: costTotal
  });
}

// 4. Modèles Image
let totalImageCost = 0;
const imageNodes = ["Création image1", "Création image2", "Generate an image"];
for (const imgNode of imageNodes) {
  if ($(imgNode).isExecuted) {
    let imgCost = unitPricing["default_image"];
    if (imgNode.includes("image2")) imgCost = unitPricing["models/gemini-3.1-flash-image"];
    else if (imgNode.includes("Generate an image")) imgCost = unitPricing["gpt-image-1-mini"];
    else imgCost = unitPricing["models/gemini-2.5-flash-image"];

    totalImageCost += imgCost;
    breakdown.push({
      node: imgNode,
      type: "image_generation",
      cost_usd: imgCost
    });
  }
}

// 5. Modèles Vidéo
let totalVideoCost = 0;
const videoNodes = ["video_story", "Generate a video"];
for (const vidNode of videoNodes) {
  if ($(vidNode).isExecuted) {
    let vidCost = unitPricing["default_video"];
    if (vidNode === "Generate a video") vidCost = unitPricing["sora-2"];
    else vidCost = unitPricing["models/veo-3.1-lite-generate-preview"];

    totalVideoCost += vidCost;
    breakdown.push({
      node: vidNode,
      type: "video_generation",
      cost_usd: vidCost
    });
  }
}

const finalTotalCostUsd = Number((titleCostUsd + totalCostFromLLM + totalImageCost + totalVideoCost).toFixed(6));

return [{
  json: {
    story_id: storyId,
    total_cost_usd: finalTotalCostUsd,
    total_input_tokens: totalInputTokens,
    total_output_tokens: totalOutputTokens,
    breakdown: breakdown,
    timestamp: new Date().toISOString()
  }
}];
